import pandas as pd
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/rheology.csv"

# Read the CSV file
df = pd.read_csv(DATA_FILE)

# Extract columns
x = df["Angular frequency (rad/s)"].tolist()
g_prime = df["Storage modulus G' (Pa)"].tolist()
g_double_prime = df["Loss modulus G'' (Pa)"].tolist()

# Build ECharts option
option = {
    "tooltip": {
        "trigger": "axis",
        "formatter": None  # default formatter works fine
    },
    "legend": {
        "data": ["G'", "G''"],
        "top": "5%"
    },
    "grid": {
        "left": "10%",
        "right": "12%",
        "bottom": "15%",
        "containLabel": True
    },
    "xAxis": [
        {
            "type": "log",
            "name": "Angular frequency (rad/s)",
            "nameLocation": "middle",
            "nameGap": 30,
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR"
            }
        }
    ],
    "yAxis": [
        {
            "type": "log",
            "name": "G' (Pa)",
            "position": "left",
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR"
            }
        },
        {
            "type": "log",
            "name": "G'' (Pa)",
            "position": "right",
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR"
            }
        }
    ],
    "series": [
        {
            "name": "G'",
            "type": "line",
            "xAxisIndex": 0,
            "yAxisIndex": 0,
            "data": [[xi, yi] for xi, yi in zip(x, g_prime)],
            "smooth": False,
            "symbol": "circle",
            "symbolSize": 6,
            "lineStyle": {
                "width": 2
            }
        },
        {
            "name": "G''",
            "type": "line",
            "xAxisIndex": 0,
            "yAxisIndex": 1,
            "data": [[xi, yi] for xi, yi in zip(x, g_double_prime)],
            "smooth": False,
            "symbol": "triangle",
            "symbolSize": 8,
            "lineStyle": {
                "width": 2
            }
        }
    ]
}

output = {
    "figures": [
        {
            "name": "plot1",
            "option": option,
            "width": 614,
            "height": 442,
            "dpi": 300,
            "formats": ["png"]
        }
    ]
}

print(json.dumps(output, ensure_ascii=False))
